window.VeilGardeData.files["Sources-VeilWatermark"] = {"group":"Sources-VeilWatermark","files":[{"path":"Sources/VeilWatermark/Acceptance/WatermarkAcceptance.swift","status":"added","lang":"swift","hunks":[[1,0,1,171]],"header":{"lines":[1,22],"target":"VeilWatermark","what":[6,10],"pin":[11,21],"in":null,"out":null,"style":"swift"},"marks":[],"first":1088,"scopes":[["S","AcceptanceSettings",null,"public",29,29,[29,63],43,null,-1,0,"a"],["i","init",[],"public",40,40,[40,18],40,null,0,8,"a"],["v","options",null,"",42,42,[42,30],42,null,0,8,"a"],["S","AcceptanceImage",null,"public",45,45,[45,49],62,null,-1,0,"a"],["S","Crop",null,"public",46,46,[46,42],46,null,3,8,"a"],["S","AcceptanceSummary",null,"public",64,64,[64,51],79,null,-1,0,"a"],["S","AcceptanceReport",null,"public",81,81,[81,50],85,null,-1,0,"a"],["E","WatermarkAcceptance",null,"public",87,87,[87,32],171,null,-1,0,"a",[]],["f","run",["_","settings","note","measured"],"public static",89,89,[90,137],137,null,7,0,"a"],["f","summarize",["_","settings"],"public static",139,139,[139,111],170,null,7,0,"a"],["f","median",["_"],"",141,141,[141,45],141,null,9,12,"a"]],"old":"","new":"//\n//  WatermarkAcceptance.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Whether v1 works, measured: for each sampled image, a self-match, a random 50%-area crop\n//        at a random pixel offset (its match and the offset it recovers), a JPEG q75 re-encode,\n//        a cross match of the crop against another image's signature (the false matches), and,\n//        on every fourth image, the crop resized to 0.9× and 0.75× (where v1 is expected to\n//        break). Then the kill criterion, stated before the run.\n//  PIN:  The acceptance, fixed before the run: self-match 100%; the crop matches (score ≥ 0.75, ≥ 256 bits)\n//        with its offset within one tile in at least 60% of images; the median JPEG q75 score is\n//        at least 0.75; some threshold reaches ≥ 80% crop recall at ≤ 5% cross false matches.\n//        Failing any kills v1 (the fallbacks: LV bits, rank-quantized FR). The JPEG keeps the\n//        grid in place, so it is matched at phase 0; everything else uses the full phase search.\n//        Seeded by SplitMix64; nothing is written but the report and each image's row as it is\n//        measured. The resizes are half of an image's cost and no part of the criterion, so on\n//        2026-10-19, with the first 24.5 MP image taking 13.5 minutes on a shared GPU, they were\n//        cut to every fourth image (decided before any resize was measured). Each image is flattened to the\n//        8-bit bitmap the lens reads as soon as it is decoded (ImageCodec), so the crops, the JPEG\n//        and the resizes all start from exactly the pixels that were signed.\n//\n\nimport CoreGraphics\nimport Foundation\nimport VeilGardeCore\nimport VeilGardeLens\n\npublic struct AcceptanceSettings: Codable, Sendable, Equatable {\n    public var seed: UInt64 = 0\n    public var cropArea = 0.5\n    public var jpegQuality = 0.75\n    public var scales: [Double] = [0.9, 0.75]\n    /// The resizes are measured on every n-th image.\n    public var resizeEvery = 4\n    public var phases: [Int] = MatchOptions.default.phases\n    public var minimumBits = MatchOptions.default.minimumBits\n    public var threshold = MatchOptions.default.threshold\n\n    public init() {}\n\n    var options: MatchOptions { MatchOptions(phases: phases, minimumBits: minimumBits, threshold: threshold) }\n}\n\npublic struct AcceptanceImage: Codable, Sendable {\n    public struct Crop: Codable, Sendable { public var x: Int; public var y: Int; public var width: Int; public var height: Int }\n    public var path: String\n    public var label: Int\n    public var width: Int\n    public var height: Int\n    public var signedBits: Int\n    public var balance: [Double]\n    public var selfMatch: MatchResult\n    public var crop: Crop\n    public var cropMatch: MatchResult\n    /// The recovered crop origin's distance from the truth, in tiles (the larger axis).\n    public var cropOffsetError: Double\n    public var jpeg: MatchResult\n    public var cross: MatchResult\n    public var resized: [String: MatchResult]\n    public var seconds: Double\n}\n\npublic struct AcceptanceSummary: Codable, Sendable {\n    public var images: Int\n    public var selfMatchRate: Double\n    public var cropMatchRate: Double\n    public var jpegMedianScore: Double\n    public var crossFalseMatchRate: Double\n    public var crossMedianScore: Double\n    /// The best threshold for crop recall ≥ 80%, and its false-match rate.\n    public var operatingThreshold: Double?\n    public var operatingRecall: Double?\n    public var operatingFalseMatchRate: Double?\n    public var bitBalance: [Double]\n    public var resizedMatchRate: [String: Double]\n    public var killed: Bool\n    public var reasons: [String]\n}\n\npublic struct AcceptanceReport: Codable, Sendable {\n    public var settings: AcceptanceSettings\n    public var summary: AcceptanceSummary\n    public var images: [AcceptanceImage]\n}\n\npublic enum WatermarkAcceptance {\n\n    public static func run(_ images: [(url: URL, label: Int)], settings: AcceptanceSettings = AcceptanceSettings(),\n                           note: (String) -> Void = { _ in }, measured: (AcceptanceImage) -> Void = { _ in }) throws -> AcceptanceReport {\n        var rng = SplitMix64(seed: settings.seed)\n        let options = settings.options\n        // Pass 1: every signature (the cross matches need the next image's).\n        var decoded: [(URL, Int, CGImage)] = []\n        var signatures: [WatermarkSignature] = []\n        for (url, label) in images {\n            guard let raw = try? ImageDecoding.cgImage(contentsOf: url), let cg = ImageCodec.flattened(raw), min(cg.width, cg.height) >= 256 else {\n                note(\"accept: skipped \\(url.lastPathComponent)\"); continue\n            }\n            decoded.append((url, label, cg))\n            signatures.append(try Watermark.sign(cg))\n            if signatures.count % 20 == 0 { note(\"accept: signed \\(signatures.count) of \\(images.count)\") }\n        }\n        note(\"accept: signed \\(signatures.count) images (\\(images.count - signatures.count) skipped); matching\")\n        var rows: [AcceptanceImage] = []\n        for (i, (url, label, cg)) in decoded.enumerated() {\n            let started = Date()\n            let sig = signatures[i]\n            let selfMatch = Watermark.match(codes: try Watermark.phaseCodes(cg, phases: [0]), against: sig, options: options)\n            // A crop of half the area, at a random pixel offset.\n            let side = settings.cropArea.squareRoot()\n            let cw = max(64, Int(Double(cg.width) * side)), ch = max(64, Int(Double(cg.height) * side))\n            let x = rng.index(max(1, cg.width - cw + 1)), y = rng.index(max(1, cg.height - ch + 1))\n            guard let crop = ImageLoading.renderCrop(cg, CGRect(x: x, y: y, width: cw, height: ch)) else { continue }\n            let cropCodes = try Watermark.phaseCodes(crop, phases: settings.phases)\n            let cropMatch = Watermark.match(codes: cropCodes, against: sig, options: options)\n            let error = Double(max(abs(cropMatch.pixelX - x), abs(cropMatch.pixelY - y))) / 32\n            let jpegMatch = Watermark.match(codes: try Watermark.phaseCodes(try ImageCodec.recompressed(cg, as: .jpeg, quality: settings.jpegQuality), phases: [0]),\n                                            against: sig, options: options)\n            let other = signatures[(i + 1) % signatures.count]\n            let cross = Watermark.match(codes: cropCodes, against: other, options: options)\n            var resized: [String: MatchResult] = [:]\n            for scale in settings.scales where i % max(1, settings.resizeEvery) == 0 {\n                guard let r = ImageCodec.resized(crop, by: scale) else { continue }\n                resized[String(format: \"%.2f\", scale)] = Watermark.match(codes: try Watermark.phaseCodes(r, phases: settings.phases), against: sig, options: options)\n            }\n            let codes = sig.tileCodes\n            rows.append(AcceptanceImage(path: url.path, label: label, width: cg.width, height: cg.height, signedBits: sig.measuredBits, balance: codes.balance,\n                                        selfMatch: selfMatch, crop: .init(x: x, y: y, width: cw, height: ch), cropMatch: cropMatch, cropOffsetError: error,\n                                        jpeg: jpegMatch, cross: cross, resized: resized, seconds: Date().timeIntervalSince(started)))\n            measured(rows[rows.count - 1])\n            note(String(format: \"accept %d/%d %@: self %.3f, crop %.3f (%d bits, off by %.2f tiles), jpeg %.3f, cross %.3f, %.0fs\", i + 1, decoded.count,\n                        url.lastPathComponent, selfMatch.score, cropMatch.score, cropMatch.bitsCompared, error, jpegMatch.score, cross.score,\n                        rows[rows.count - 1].seconds))\n        }\n        return AcceptanceReport(settings: settings, summary: summarize(rows, settings: settings), images: rows)\n    }\n\n    public static func summarize(_ rows: [AcceptanceImage], settings: AcceptanceSettings) -> AcceptanceSummary {\n        let n = Double(max(1, rows.count))\n        func median(_ v: [Double]) -> Double { v.isEmpty ? .nan : v.sorted()[v.count / 2] }\n        let selfOK = rows.filter { $0.selfMatch.matched && $0.selfMatch.offsetX == 0 && $0.selfMatch.offsetY == 0 && $0.selfMatch.score == 1 }.count\n        let cropOK = rows.filter { $0.cropMatch.matched && $0.cropOffsetError <= 1 }.count\n        let crossFalse = rows.filter { $0.cross.matched }.count\n        // The operating point: the threshold with crop recall ≥ 80% and the fewest false matches.\n        var op: (t: Double, recall: Double, fpr: Double)? = nil\n        for k in 50...100 {\n            let t = Double(k) / 100\n            let recall = Double(rows.filter { $0.cropMatch.score >= t && $0.cropMatch.bitsCompared >= settings.minimumBits && $0.cropOffsetError <= 1 }.count) / n\n            let fpr = Double(rows.filter { $0.cross.score >= t && $0.cross.bitsCompared >= settings.minimumBits }.count) / n\n            if recall >= 0.80, op == nil || fpr < op!.fpr || (fpr == op!.fpr && t > op!.t) { op = (t, recall, fpr) }\n        }\n        var balance = [Double](repeating: 0, count: 4)\n        for k in 0..<4 { balance[k] = median(rows.map { $0.balance[k] }.filter(\\.isFinite)) }\n        var resizedRate: [String: Double] = [:]\n        for key in Set(rows.flatMap { $0.resized.keys }) {\n            let measured = rows.filter { $0.resized[key] != nil }\n            resizedRate[key] = Double(measured.filter { $0.resized[key]?.matched == true }.count) / Double(max(1, measured.count))\n        }\n        let cropRate = Double(cropOK) / n, jpegMedian = median(rows.map(\\.jpeg.score))\n        var reasons: [String] = []\n        if cropRate < 0.60 { reasons.append(String(format: \"the crop matched with its offset in %.0f%% of images, under 60%%\", cropRate * 100)) }\n        if jpegMedian < 0.75 { reasons.append(String(format: \"the median JPEG q75 score is %.3f, under 0.75\", jpegMedian)) }\n        if let op, op.fpr > 0.05 { reasons.append(String(format: \"at 80%% crop recall the fewest false matches are %.1f%%, over 5%%\", op.fpr * 100)) }\n        if op == nil { reasons.append(\"no threshold reaches 80% crop recall\") }\n        return AcceptanceSummary(images: rows.count, selfMatchRate: Double(selfOK) / n, cropMatchRate: cropRate, jpegMedianScore: jpegMedian,\n                                 crossFalseMatchRate: Double(crossFalse) / n, crossMedianScore: median(rows.map(\\.cross.score)),\n                                 operatingThreshold: op?.t, operatingRecall: op?.recall, operatingFalseMatchRate: op?.fpr, bitBalance: balance,\n                                 resizedMatchRate: resizedRate, killed: !reasons.isEmpty, reasons: reasons)\n    }\n}\n"},{"path":"Sources/VeilWatermark/Match/Matcher.swift","status":"added","lang":"swift","hunks":[[1,0,1,95]],"header":{"lines":[1,15],"target":"VeilWatermark","what":[6,8],"pin":[9,14],"in":null,"out":null,"style":"swift"},"marks":[],"first":1099,"scopes":[["S","MatchOptions",null,"public",19,19,[19,48],33,null,-1,0,"a"],["i","init",["phases","minimumBits","threshold","margin"],"public",25,25,[25,115],30,null,0,0,"a"],["S","MatchResult",null,"public",35,35,[35,56],52,null,-1,0,"a"],["v","pixelX",null,"public",48,48,[48,27],48,[47,47],2,8,"a"],["v","pixelY",null,"public",49,49,[49,27],49,null,2,8,"a"],["E","Matcher",null,"public",54,54,[54,20],95,null,-1,0,"a",[]],["f","best",["crop","stored","margin","minimumBits"],"public static",56,56,[56,154],90,[55,55],5,0,"a"],["f","zScore",["score","bits"],"public static",92,92,[92,66],94,null,5,0,"a"]],"old":"","new":"//\n//  Matcher.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Whether an image is (a crop of) a signed one, and where it sits: the image's tile codes,\n//        read at several sub-tile grid phases, slid over the signature's at every whole-tile\n//        offset; the best agreement is the match.\n//  PIN:  score = 1 − mismatched / compared bits, over the bits both grids measured; the crop is\n//        taken to lie inside the signed image, so offsets run over the containing range with a\n//        one-tile margin. zScore = (score − 0.5) / √(0.25 / bits), the agreement's distance from\n//        chance in coin-flip units. A match needs score ≥ 0.75 and ≥ 256 compared bits (the v1\n//        acceptance bar). Phases default to the 16 of {0, 8, 16, 24}² px, so\n//        some phase sits within 4 px of the signed grid on each axis.\n//\n\nimport Foundation\n\npublic struct MatchOptions: Sendable, Equatable {\n    public var phases: [Int]\n    public var minimumBits: Int\n    public var threshold: Double\n    public var margin: Int\n\n    public init(phases: [Int] = [0, 8, 16, 24], minimumBits: Int = 256, threshold: Double = 0.75, margin: Int = 1) {\n        self.phases = phases\n        self.minimumBits = minimumBits\n        self.threshold = threshold\n        self.margin = margin\n    }\n\n    public static let `default` = MatchOptions()\n}\n\npublic struct MatchResult: Codable, Sendable, Equatable {\n    /// Where the image's phase grid sits on the signed grid, in tiles.\n    public var offsetX: Int\n    public var offsetY: Int\n    /// The image's grid phase that matched, in pixels.\n    public var phaseX: Int\n    public var phaseY: Int\n    public var score: Double\n    public var bitsCompared: Int\n    public var zScore: Double\n    public var matched: Bool\n\n    /// The signed-image pixel the image's top-left corresponds to (offset · 32 − phase).\n    public var pixelX: Int { offsetX * 32 - phaseX }\n    public var pixelY: Int { offsetY * 32 - phaseY }\n\n    public static let none = MatchResult(offsetX: 0, offsetY: 0, phaseX: 0, phaseY: 0, score: 0, bitsCompared: 0, zScore: 0, matched: false)\n}\n\npublic enum Matcher {\n    /// The best whole-tile offset of `crop` on `stored`: (dx, dy, mismatches, compared bits), or nil.\n    public static func best(crop: TileCodeGrid, stored: TileCodeGrid, margin: Int = 1, minimumBits: Int) -> (dx: Int, dy: Int, score: Double, bits: Int)? {\n        var best: (Int, Int, Double, Int)? = nil\n        let CR = crop.rows, CC = crop.cols, SR = stored.rows, SC = stored.cols\n        guard CR > 0, CC > 0, SR > 0, SC > 0 else { return nil }\n        crop.bits.withUnsafeBufferPointer { cb in\n            crop.masks.withUnsafeBufferPointer { cm in\n                stored.bits.withUnsafeBufferPointer { sb in\n                    stored.masks.withUnsafeBufferPointer { sm in\n                        let lowY = min(-margin, SR - CR + margin), highY = max(SR - CR + margin, -margin)\n                        let lowX = min(-margin, SC - CC + margin), highX = max(SC - CC + margin, -margin)\n                        for dy in lowY...highY {\n                            for dx in lowX...highX {\n                                var bits = 0, bad = 0\n                                let i0 = max(0, -dy), i1 = min(CR, SR - dy)\n                                let j0 = max(0, -dx), j1 = min(CC, SC - dx)\n                                guard i0 < i1, j0 < j1 else { continue }\n                                for i in i0..<i1 {\n                                    let crow = i * CC, srow = (i + dy) * SC + dx\n                                    for j in j0..<j1 {\n                                        let m = cm[crow + j] & sm[srow + j]\n                                        bits += m.nonzeroBitCount\n                                        bad += ((cb[crow + j] ^ sb[srow + j]) & m).nonzeroBitCount\n                                    }\n                                }\n                                guard bits >= minimumBits else { continue }\n                                let score = 1 - Double(bad) / Double(bits)\n                                if best == nil || score > best!.2 || (score == best!.2 && bits > best!.3) { best = (dx, dy, score, bits) }\n                            }\n                        }\n                    }\n                }\n            }\n        }\n        return best.map { (dx: $0.0, dy: $0.1, score: $0.2, bits: $0.3) }\n    }\n\n    public static func zScore(score: Double, bits: Int) -> Double {\n        bits > 0 ? (score - 0.5) / (0.25 / Double(bits)).squareRoot() : 0\n    }\n}\n"},{"path":"Sources/VeilWatermark/Sections/Sectioning.swift","status":"added","lang":"swift","hunks":[[1,0,1,48]],"header":{"lines":[1,13],"target":"VeilWatermark","what":[6,9],"pin":[10,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":1107,"scopes":[["E","Sectioning",null,"public",15,15,[15,23],48,null,-1,0,"a",[]],["f","sectionRows",["_"],"public static",18,18,[18,55],18,null,0,8,"a"],["f","sectionCols",["_"],"public static",19,19,[19,55],19,null,0,8,"a"],["f","pack",["_"],"public static",21,21,[21,85],33,null,0,0,"a"],["f","unpack",["codes","masks","rows","cols"],"public static",35,35,[35,102],47,null,0,0,"a"]],"old":"","new":"//\n//  Sectioning.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: How tile codes are kept: the grid cut into sections of 4×4 tiles (128 px), each a 64-bit\n//        word of its sixteen nibbles in row-major tile order, with a 64-bit mask beside it, the\n//        sections themselves in row-major order. A crop contains whole sections of the image it\n//        came from, and the concatenation of section words is the signature.\n//  PIN:  No hash folds the tiles: a section word keeps every tile's nibble in place, so a bit\n//        that differs is one bit of Hamming distance, not a different hash. Tiles past the\n//        grid's edge in a border section are masked.\n//\n\npublic enum Sectioning {\n    public static let side = 4\n\n    public static func sectionRows(_ rows: Int) -> Int { (rows + side - 1) / side }\n    public static func sectionCols(_ cols: Int) -> Int { (cols + side - 1) / side }\n\n    public static func pack(_ g: TileCodeGrid) -> (codes: [UInt64], masks: [UInt64]) {\n        let sr = sectionRows(g.rows), sc = sectionCols(g.cols)\n        var codes = [UInt64](repeating: 0, count: sr * sc), masks = [UInt64](repeating: 0, count: sr * sc)\n        for r in 0..<g.rows {\n            for c in 0..<g.cols {\n                let s = (r / side) * sc + c / side\n                let k = UInt64(((r % side) * side + c % side) * 4)\n                codes[s] |= UInt64(g.bits[r * g.cols + c] & 0xF) << k\n                masks[s] |= UInt64(g.masks[r * g.cols + c] & 0xF) << k\n            }\n        }\n        return (codes, masks)\n    }\n\n    public static func unpack(codes: [UInt64], masks: [UInt64], rows: Int, cols: Int) -> TileCodeGrid {\n        let sc = sectionCols(cols)\n        var bits = [UInt8](repeating: 0, count: rows * cols), m = [UInt8](repeating: 0, count: rows * cols)\n        for r in 0..<rows {\n            for c in 0..<cols {\n                let s = (r / side) * sc + c / side\n                let k = UInt64(((r % side) * side + c % side) * 4)\n                bits[r * cols + c] = UInt8((codes[s] >> k) & 0xF)\n                m[r * cols + c] = UInt8((masks[s] >> k) & 0xF)\n            }\n        }\n        return TileCodeGrid(rows: rows, cols: cols, bits: bits, masks: m)\n    }\n}\n"},{"path":"Sources/VeilWatermark/Signature/TileCodes.swift","status":"added","lang":"swift","hunks":[[1,0,1,60]],"header":{"lines":[1,13],"target":"VeilWatermark","what":[6,8],"pin":[9,12],"in":null,"out":null,"style":"swift"},"marks":[],"first":1112,"scopes":[["S","TileCodeGrid",null,"public",15,15,[15,48],60,null,-1,0,"a"],["i","init",["rows","cols","bits","masks"],"public",25,25,[25,69],30,null,0,0,"a"],["i","init",["_"],"public",32,32,[32,36],48,null,0,0,"a"],["v","measuredBits",null,"public",50,50,[50,33],50,null,0,8,"a"],["v","balance",null,"public",53,53,[53,33],59,[52,52],0,0,"a"]],"old":"","new":"//\n//  TileCodes.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: The watermark's alphabet: for every tile, four ordinal bits saying whether its fragility\n//        rate exceeds its forward neighbours' (east, south, south-east, north-east), with a mask\n//        for the comparisons that fall outside the grid.\n//  PIN:  Ordinal, so a monotone change of the residual's gain (a brighter print, a softer\n//        re-encode) leaves the code alone. Bit k of a tile's nibble: 0 east, 1 south,\n//        2 south-east, 3 north-east; an equal pair reads 0. A comparison is masked when the\n//        neighbour is outside the grid, so a crop never compares against tiles it lacks.\n//\n\npublic struct TileCodeGrid: Sendable, Equatable {\n    public static let neighbours = [(0, 1), (1, 0), (1, 1), (-1, 1)]   // (dr, dc): E, S, SE, NE\n\n    public var rows: Int\n    public var cols: Int\n    /// Per tile, its four bits in the low nibble.\n    public var bits: [UInt8]\n    /// Per tile, which of its four bits were measured.\n    public var masks: [UInt8]\n\n    public init(rows: Int, cols: Int, bits: [UInt8], masks: [UInt8]) {\n        self.rows = rows\n        self.cols = cols\n        self.bits = bits\n        self.masks = masks\n    }\n\n    public init(_ g: FragilityGrid) {\n        rows = g.rows\n        cols = g.cols\n        bits = [UInt8](repeating: 0, count: g.rows * g.cols)\n        masks = [UInt8](repeating: 0, count: g.rows * g.cols)\n        for r in 0..<g.rows {\n            for c in 0..<g.cols {\n                let v = g[r, c]\n                for (k, (dr, dc)) in Self.neighbours.enumerated() {\n                    let nr = r + dr, nc = c + dc\n                    guard nr >= 0, nr < g.rows, nc >= 0, nc < g.cols else { continue }\n                    masks[r * g.cols + c] |= 1 << k\n                    if v > g[nr, nc] { bits[r * g.cols + c] |= 1 << k }\n                }\n            }\n        }\n    }\n\n    public var measuredBits: Int { masks.reduce(0) { $0 + $1.nonzeroBitCount } }\n\n    /// The share of measured bits that are 1, per bit position.\n    public var balance: [Double] {\n        (0..<4).map { k in\n            var ones = 0, total = 0\n            for i in bits.indices where masks[i] & (1 << k) != 0 { total += 1; if bits[i] & (1 << k) != 0 { ones += 1 } }\n            return total > 0 ? Double(ones) / Double(total) : .nan\n        }\n    }\n}\n"},{"path":"Sources/VeilWatermark/Signature/WatermarkSignature.swift","status":"added","lang":"swift","hunks":[[1,0,1,123]],"header":{"lines":[1,13],"target":"VeilWatermark","what":[6,7],"pin":[8,12],"in":null,"out":null,"style":"swift"},"marks":[[53,"Binary and text"]],"first":1117,"scopes":[["S","WatermarkSignature",null,"public",18,18,[18,54],92,null,-1,0,"a"],["i","init",["grid"],"public",30,30,[30,36],37,null,0,0,"a"],["i","init",["version","tile","section","rows","cols","codes","masks"],"public",39,39,[39,151],47,null,0,0,"a"],["v","tileCodes",null,"public",49,49,[49,39],49,null,0,8,"a"],["v","measuredBits",null,"public",51,51,[51,33],51,null,0,8,"a"],["v","binary",null,"public",55,55,[55,28],63,null,0,0,"a"],["f","u32",["_"],"",58,58,[58,27],58,null,5,12,"a"],["i","init",["binary"],"public",65,65,[65,39],77,null,0,0,"a"],["f","u32",["_"],"",68,68,[68,35],68,null,7,12,"a"],["f","u64",["_"],"",69,69,[69,38],69,null,7,12,"a"],["v","cid",null,"public",79,79,[79,27],79,null,0,8,"a"],["v","compact",null,"public",81,81,[81,31],83,null,0,0,"a"],["i","init",["compact"],"public",85,85,[85,42],91,null,0,0,"a"],["X","WatermarkSignature",null,"",94,94,[94,38],123,null,-1,0,"a"],["E","CodingKeys",null,"",95,95,[95,39],95,null,13,8,"a",[]],["f","encode",["to"],"public",97,97,[97,51],107,null,13,0,"a"],["i","init",["from"],"public",109,109,[109,46],122,null,13,0,"a"],["f","words",["_"],"",111,111,[111,55],116,null,16,4,"a"]],"old":"","new":"//\n//  WatermarkSignature.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: An image's watermark: its tile grid's size, its section words and their masks, and a\n//        content id. Carried as JSON, as a compact binary, or as text (\"vw1:\" + base64url).\n//  PIN:  Binary v1, little-endian: \"VW1\\0\", version, tile (32), section (4), a zero byte, rows and\n//        cols of the tile grid (u32 each), the section count (u32), the codes, the masks (u64\n//        each). cid = SHA-256 of exactly those bytes, hex, so two signatures of the same pixels\n//        are the same id. JSON writes the words as 16-digit hex (a 64-bit number is not safe in\n//        every JSON reader).\n//\n\nimport Foundation\nimport VeilGardeCore\n\npublic struct WatermarkSignature: Sendable, Equatable {\n    public static let currentVersion = 1\n    public static let magic = Data(\"VW1\\0\".utf8)\n\n    public var version: Int\n    public var tile: Int\n    public var section: Int\n    public var rows: Int\n    public var cols: Int\n    public var codes: [UInt64]\n    public var masks: [UInt64]\n\n    public init(grid: TileCodeGrid) {\n        version = Self.currentVersion\n        tile = 32\n        section = Sectioning.side\n        rows = grid.rows\n        cols = grid.cols\n        (codes, masks) = Sectioning.pack(grid)\n    }\n\n    public init(version: Int = currentVersion, tile: Int = 32, section: Int = Sectioning.side, rows: Int, cols: Int, codes: [UInt64], masks: [UInt64]) {\n        self.version = version\n        self.tile = tile\n        self.section = section\n        self.rows = rows\n        self.cols = cols\n        self.codes = codes\n        self.masks = masks\n    }\n\n    public var tileCodes: TileCodeGrid { Sectioning.unpack(codes: codes, masks: masks, rows: rows, cols: cols) }\n\n    public var measuredBits: Int { masks.reduce(0) { $0 + $1.nonzeroBitCount } }\n\n    // MARK: Binary and text\n\n    public var binary: Data {\n        var d = Self.magic\n        d.append(contentsOf: [UInt8(version), UInt8(tile), UInt8(section), 0])\n        func u32(_ v: Int) { withUnsafeBytes(of: UInt32(v).littleEndian) { d.append(contentsOf: $0) } }\n        u32(rows); u32(cols); u32(codes.count)\n        for w in codes { withUnsafeBytes(of: w.littleEndian) { d.append(contentsOf: $0) } }\n        for w in masks { withUnsafeBytes(of: w.littleEndian) { d.append(contentsOf: $0) } }\n        return d\n    }\n\n    public init(binary d: Data) throws {\n        let b = [UInt8](d)\n        guard b.count >= 20, Data(b[0..<4]) == Self.magic else { throw VeilGardeFailure.data(\"not a VW1 watermark signature\") }\n        func u32(_ at: Int) -> Int { Int(UInt32(b[at]) | UInt32(b[at + 1]) << 8 | UInt32(b[at + 2]) << 16 | UInt32(b[at + 3]) << 24) }\n        func u64(_ at: Int) -> UInt64 { (0..<8).reduce(UInt64(0)) { $0 | UInt64(b[at + $1]) << (8 * UInt64($1)) } }\n        let n = u32(16)\n        guard b.count == 20 + 16 * n else { throw VeilGardeFailure.data(\"a VW1 signature of \\(n) sections must be \\(20 + 16 * n) bytes, not \\(b.count)\") }\n        let rows = u32(8), cols = u32(12)\n        guard n == Sectioning.sectionRows(rows) * Sectioning.sectionCols(cols) else { throw VeilGardeFailure.data(\"a \\(rows)×\\(cols) grid has \\(Sectioning.sectionRows(rows) * Sectioning.sectionCols(cols)) sections, not \\(n)\") }\n        self.init(version: Int(b[4]), tile: Int(b[5]), section: Int(b[6]), rows: rows, cols: cols,\n                  codes: (0..<n).map { u64(20 + 8 * $0) }, masks: (0..<n).map { u64(20 + 8 * (n + $0)) })\n        guard version == Self.currentVersion, tile == 32, section == Sectioning.side else { throw VeilGardeFailure.data(\"an unsupported watermark signature (version \\(version), tile \\(tile), section \\(section))\") }\n    }\n\n    public var cid: String { ContentHash.sha256Hex(binary) }\n\n    public var compact: String {\n        \"vw1:\" + binary.base64EncodedString().replacingOccurrences(of: \"+\", with: \"-\").replacingOccurrences(of: \"/\", with: \"_\").replacingOccurrences(of: \"=\", with: \"\")\n    }\n\n    public init(compact s: String) throws {\n        guard s.hasPrefix(\"vw1:\") else { throw VeilGardeFailure.data(\"a compact watermark starts with vw1:\") }\n        var b64 = String(s.dropFirst(4)).replacingOccurrences(of: \"-\", with: \"+\").replacingOccurrences(of: \"_\", with: \"/\")\n        while b64.count % 4 != 0 { b64 += \"=\" }\n        guard let d = Data(base64Encoded: b64) else { throw VeilGardeFailure.data(\"the watermark's base64url does not decode\") }\n        try self.init(binary: d)\n    }\n}\n\nextension WatermarkSignature: Codable {\n    enum CodingKeys: String, CodingKey { case version, tile, section, rows, cols, codes, masks, cid }\n\n    public func encode(to encoder: Encoder) throws {\n        var c = encoder.container(keyedBy: CodingKeys.self)\n        try c.encode(version, forKey: .version)\n        try c.encode(tile, forKey: .tile)\n        try c.encode(section, forKey: .section)\n        try c.encode(rows, forKey: .rows)\n        try c.encode(cols, forKey: .cols)\n        try c.encode(codes.map { String(format: \"%016llx\", $0) }, forKey: .codes)\n        try c.encode(masks.map { String(format: \"%016llx\", $0) }, forKey: .masks)\n        try c.encode(cid, forKey: .cid)\n    }\n\n    public init(from decoder: Decoder) throws {\n        let c = try decoder.container(keyedBy: CodingKeys.self)\n        func words(_ k: CodingKeys) throws -> [UInt64] {\n            try c.decode([String].self, forKey: k).map {\n                guard let w = UInt64($0, radix: 16) else { throw VeilGardeFailure.data(\"a watermark word \\($0) is not hex\") }\n                return w\n            }\n        }\n        self.init(version: try c.decode(Int.self, forKey: .version), tile: try c.decode(Int.self, forKey: .tile), section: try c.decode(Int.self, forKey: .section),\n                  rows: try c.decode(Int.self, forKey: .rows), cols: try c.decode(Int.self, forKey: .cols), codes: try words(.codes), masks: try words(.masks))\n        if let stated = try c.decodeIfPresent(String.self, forKey: .cid), stated != cid {\n            throw VeilGardeFailure.data(\"the watermark's cid \\(stated.prefix(12)) does not match its words (\\(cid.prefix(12)))\")\n        }\n    }\n}\n"},{"path":"Sources/VeilWatermark/VeilWatermark.swift","status":"added","lang":"swift","hunks":[[1,0,1,11]],"header":{"lines":[1,9],"target":"VeilWatermark","what":[6,8],"pin":null,"in":null,"out":null,"style":"swift"},"marks":[],"first":1135,"scopes":[],"old":"","new":"//\n//  VeilWatermark.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: A passive, crop-robust signature read off an image's per-tile warp fragility pattern:\n//        sectioned tile codes that a crop of the same image reproduces, matched by offset and\n//        grid phase. Re-exports the Lens, whose residual it reuses rather than forks.\n//\n\n@_exported import VeilGardeLens\n"},{"path":"Sources/VeilWatermark/Watermark.swift","status":"added","lang":"swift","hunks":[[1,0,1,59]],"header":{"lines":[1,14],"target":"VeilWatermark","what":[6,8],"pin":[9,13],"in":null,"out":null,"style":"swift"},"marks":[],"first":1135,"scopes":[["E","Watermark",null,"public",20,20,[20,22],59,null,-1,0,"a",[]],["f","sign",["_"],"public static",21,21,[21,72],24,null,0,0,"a"],["f","phaseCodes",["_","phases"],"public static",27,27,[27,146],37,[26,26],0,0,"a"],["f","match",["codes","against","options"],"public static",39,39,[40,78],54,null,0,0,"a"],["f","match",["_","against","options"],"public static",56,56,[56,139],58,null,0,0,"a"]],"old":"","new":"//\n//  Watermark.swift\n//  VeilWatermark\n//  SPDX-License-Identifier: GPL-3.0-only\n//\n//  WHAT: Sign an image (its native-resolution tile codes, sectioned) and match an image against a\n//        signature (its codes at every grid phase, slid over the signature's). Nothing is added\n//        to the pixels: the mark is what the warp residual already reads off them.\n//  PIN:  v1 is a design under measurement, not a claim: `veilgarde watermark accept` runs the\n//        acceptance and its kill criterion (docs/site/08-watermark.html). Signing reads the grid at phase\n//        (0, 0); a self-match therefore lands at offset 0, phase 0, score 1. Resizing is out of\n//        scope for v1: a resized image changes its tiles and is measured only to show where it\n//        breaks.\n//\n\nimport CoreGraphics\nimport Foundation\nimport VeilGardeLens\n\npublic enum Watermark {\n    public static func sign(_ cg: CGImage) throws -> WatermarkSignature {\n        defer { LensRuntime.releaseMemory() }\n        return WatermarkSignature(grid: TileCodeGrid(try NativePlane(cg).fragility()))\n    }\n\n    /// The image's tile codes at each phase, for matching against one or more signatures.\n    public static func phaseCodes(_ cg: CGImage, phases: [Int] = MatchOptions.default.phases) throws -> [(px: Int, py: Int, codes: TileCodeGrid)] {\n        defer { LensRuntime.releaseMemory() }\n        let plane = try NativePlane(cg)\n        var out: [(Int, Int, TileCodeGrid)] = []\n        for py in phases {\n            for px in phases {\n                out.append((px, py, TileCodeGrid(plane.fragility(originX: px, originY: py))))\n            }\n        }\n        return out\n    }\n\n    public static func match(codes: [(px: Int, py: Int, codes: TileCodeGrid)], against signature: WatermarkSignature,\n                             options: MatchOptions = .default) -> MatchResult {\n        let stored = signature.tileCodes\n        var best = MatchResult.none\n        for (px, py, crop) in codes {\n            guard let b = Matcher.best(crop: crop, stored: stored, margin: options.margin, minimumBits: options.minimumBits) else { continue }\n            if b.score > best.score || (b.score == best.score && b.bits > best.bitsCompared) {\n                // The phase grid starts px into the image: its tile 0 sits at signed tile dx, so\n                // the image's own origin is dx·32 − px on the signed image.\n                best = MatchResult(offsetX: b.dx, offsetY: b.dy, phaseX: px, phaseY: py, score: b.score, bitsCompared: b.bits,\n                                   zScore: Matcher.zScore(score: b.score, bits: b.bits), matched: false)\n            }\n        }\n        best.matched = best.score >= options.threshold && best.bitsCompared >= options.minimumBits\n        return best\n    }\n\n    public static func match(_ cg: CGImage, against signature: WatermarkSignature, options: MatchOptions = .default) throws -> MatchResult {\n        match(codes: try phaseCodes(cg, phases: options.phases), against: signature, options: options)\n    }\n}\n"}]};
